from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime
from typing import Any

from packaging.specifiers import InvalidSpecifier, SpecifierSet
from packaging.version import InvalidVersion, Version


def _parse_upload_time(value: Any) -> datetime | None:
    """Parse an ``upload_time_iso_8601`` value, returning ``None`` if invalid."""
    if not isinstance(value, str) or not value:
        return None
    try:
        return datetime.fromisoformat(value)
    except ValueError:
        return None


@dataclass(frozen=True)
class Release:
    """A single package release (one version) aggregated across its distributions."""

    version: Version
    upload_time: datetime
    yanked: bool
    requires_python: SpecifierSet | None

    @classmethod
    def _from_distributions(
        cls, version: Version, distributions: list[dict[str, Any]]
    ) -> Release | None:
        """Build a :class:`Release` from its distribution dicts.

        Returns ``None`` when the release should be dropped: it has no
        distributions, or none of its distributions have a parseable
        ``upload_time_iso_8601`` field.
        """
        if not distributions:
            return None

        upload_times = [
            parsed
            for dist in distributions
            if (parsed := _parse_upload_time(dist.get("upload_time_iso_8601"))) is not None
        ]
        if not upload_times:
            return None

        # A release is considered yanked only if *every* distribution is yanked.
        yanked = all(bool(dist.get("yanked", False)) for dist in distributions)

        # Use the first non-empty, valid ``requires_python`` value.
        requires_python: SpecifierSet | None = None
        for dist in distributions:
            raw = dist.get("requires_python")
            if not raw:
                continue
            try:
                requires_python = SpecifierSet(raw)
            except InvalidSpecifier:
                continue
            break

        return cls(
            version=version,
            upload_time=min(upload_times),
            yanked=yanked,
            requires_python=requires_python,
        )


@dataclass
class Package:
    """A PyPI package and its releases."""

    name: str
    releases: dict[Version, Release] = field(default_factory=dict)

    @classmethod
    def from_json(cls, data: dict[str, Any]) -> Package:
        """Parse a PyPI JSON API response into a :class:`Package`.

        Releases are dropped when they have no distributions, when none of their
        distributions carry a parseable upload time, or when the version string
        is not a valid PEP 440 version.
        """
        info = data.get("info") or {}
        name = info.get("name") or ""

        releases: dict[Version, Release] = {}
        for raw_version, distributions in (data.get("releases") or {}).items():
            if not isinstance(distributions, list):
                continue
            try:
                version = Version(raw_version)
            except InvalidVersion:
                continue
            release = Release._from_distributions(version, distributions)
            if release is None:
                continue
            releases[version] = release

        return cls(name=name, releases=releases)

    @property
    def versions(self) -> tuple[Version, ...]:
        """All valid release versions, sorted in ascending order."""
        return tuple(sorted(self.releases))

    @property
    def latest_version(self) -> Version | None:
        """Highest stable (non-pre-release, non-dev, non-yanked) version, or ``None``."""
        stable = [
            version
            for version, release in self.releases.items()
            if not version.is_prerelease and not version.is_devrelease and not release.yanked
        ]
        return max(stable) if stable else None

    def get_release(self, version: str | Version) -> Release | None:
        """Return the :class:`Release` for ``version``, or ``None`` if absent."""
        if isinstance(version, str):
            try:
                version = Version(version)
            except InvalidVersion:
                return None
        return self.releases.get(version)
