from __future__ import annotations

import asyncio
import json
import os
import time
from collections.abc import Iterable
from urllib.error import HTTPError, URLError
from urllib.request import urlopen

from ._models import Package

DEFAULT_BASE_URL = "https://pypi.org"

# Transient statuses that are worth retrying.
_RETRYABLE_STATUS_CODES = frozenset({429, 500, 502, 503, 504})

# Total number of attempts (initial request + retries).
_MAX_ATTEMPTS = 3

_cache: dict[str, Package] = {}


class PyPIError(RuntimeError):
    """Raised for all unrecoverable errors when fetching from PyPI."""


def _base_url() -> str:
    override = os.environ.get("PYPI_URL")
    if override:
        return override.rstrip("/")
    return DEFAULT_BASE_URL


def _fetch_raw(name: str) -> bytes:
    """Fetch the raw JSON body for ``name``, retrying transient failures."""
    url = f"{_base_url()}/pypi/{name}/json"
    last_error: BaseException | None = None

    for attempt in range(_MAX_ATTEMPTS):
        try:
            with urlopen(url) as response:
                return response.read()
        except HTTPError as e:
            if e.code == 404:
                raise PyPIError(f"Package not found: {name!r}") from e
            if e.code not in _RETRYABLE_STATUS_CODES:
                raise PyPIError(f"HTTP {e.code} error while fetching {name!r}") from e
            last_error = e
        except (URLError, ConnectionResetError) as e:
            last_error = e

        # Sleep before retrying, but not after the final attempt.
        if attempt < _MAX_ATTEMPTS - 1:
            time.sleep(2**attempt)

    raise PyPIError(
        f"Failed to fetch {name!r} after {_MAX_ATTEMPTS} attempts"
    ) from last_error


def get_package(name: str) -> Package:
    """Fetch package metadata for ``name``, memoizing the result in memory."""
    if name in _cache:
        return _cache[name]

    raw = _fetch_raw(name)
    try:
        data = json.loads(raw)
    except (ValueError, TypeError) as e:
        raise PyPIError(f"Invalid JSON response for {name!r}") from e

    if not isinstance(data, dict):
        raise PyPIError(f"Unexpected response for {name!r}: expected a JSON object")

    package = Package.from_json(data)
    _cache[name] = package
    return package


def clear_cache() -> None:
    """Clear the in-memory cache used by :func:`get_package`."""
    _cache.clear()


async def aget_package(name: str) -> Package:
    """Async wrapper around :func:`get_package`."""
    return await asyncio.to_thread(get_package, name)


async def aget_packages(names: Iterable[str]) -> list[Package]:
    """Fetch multiple packages concurrently, preserving input order."""
    names = list(names)
    return await asyncio.gather(*(aget_package(name) for name in names))
